        mapping = {
            0: cascade,
            1: cascade,
            2: track,
            3: s_track,
            4: track,
            5: doublebang,
            6: doublebang,
            7: cascade,
            8: track,
            9: cascade
        };
        return mapping[int(x)];
    }
